sp_widget.client_script:
api.controller = function($scope, $interval, $timeout) {
  var c = this;

  // ── Initialize all state ──────────────────────────────────
  c.data.fileReady  = false;
  c.data.fileName   = '';
  c.data.processing = false;
  c.data.result     = null;
  c.data.error      = null;
  c.data.sysId      = null;
  c.data.statusMsg  = '';
  c.data.action     = null;
  c.dragging        = false;
  c.rawFile         = null;

  var pollTimer = null;
  var pollCount = 0;
  var MAX_POLLS = 36;

  // ── File selection via click ──────────────────────────────
  c.triggerUpload = function() {
    document.getElementById('ocrFileInput').click();
  };

  c.onFileSelect = function(event) {
    var file = event.target.files[0];
    if (!file) return;
    if (file.type !== 'application/pdf') {
      $timeout(function() {
        c.data.error = 'Please select a valid PDF file.';
      });
      return;
    }
    c.readFile(file);
  };

c.getRatioTable = function(ratios) {
  if (!ratios) return [];

  var rows = [];
  var seen = {}; // 🔥 to remove duplicates

  // Normalize
  ratios = ratios.replace(/\n/g, '|');

  var parts = ratios.split('|');

  for (var i = 0; i < parts.length; i++) {

    var key = parts[i].trim();
    var value = '';

    if (!key || key === '-' || key.length < 2) continue;

    // Next item is value
    if (i < parts.length - 1) {
      value = parts[i + 1].trim();
      i++;
    }

    // Clean invalid values
    if (!value || value === '-') value = '-';

    // 🔥 REMOVE DUPLICATES
    if (!seen[key]) {
      rows.push({
        key: key,
        value: value
      });
      seen[key] = true;
    }
  }

  return rows;
};

  // ── Drag and drop ─────────────────────────────────────────
  c.onDragOver = function(event) {
    event.preventDefault();
    c.dragging = true;
  };

  c.onDrop = function(event) {
    event.preventDefault();
    c.dragging = false;
    var file = event.dataTransfer && event.dataTransfer.files[0];
    if (!file) return;
    if (file.type !== 'application/pdf') {
      $timeout(function() {
        c.data.error = 'Please drop a valid PDF file.';
      });
      return;
    }
    c.readFile(file);
  };

  // ── Store raw file — use $timeout to safely update scope ──
  c.readFile = function(file) {
    c.rawFile = file;
    $timeout(function() {
      c.data.error     = null;
      c.data.fileName  = file.name;
      c.data.fileReady = true;
    });
  };

  // ── Phase 1: Create empty record ──────────────────────────
  c.processDocument = function() {
    if (!c.rawFile) return;
    c.data.processing = true;
    c.data.error      = null;
    c.data.statusMsg  = 'Creating record...';
    c.data.action     = 'create_record';

    c.server.update().then(function() {
      if (c.data.serverError) {
        c.data.processing  = false;
        c.data.error       = c.data.serverError;
        c.data.serverError = null;
        return;
      }
      c.data.statusMsg = 'Uploading PDF...';
      c.uploadViaApi(c.rawFile, c.data.sysId);
    });
  };

  // ── Upload PDF ────────────────────────────────────────────
  c.uploadViaApi = function(file, sysId) {
    var url = '/api/now/attachment/file'
      + '?table_name=x_birl3_clm_corpository_ocr'
      + '&table_sys_id=' + sysId
      + '&file_name=' + encodeURIComponent(file.name);

    var userToken = window.g_ck || '';

    var xhr = new XMLHttpRequest();
    xhr.open('POST', url, true);
    xhr.setRequestHeader('Content-Type', 'application/pdf');
    xhr.setRequestHeader('Accept', 'application/json');
    xhr.setRequestHeader('X-UserToken', userToken);

    xhr.onload = function() {
      if (xhr.status === 200 || xhr.status === 201) {
        $timeout(function() {
          c.data.statusMsg = 'OCR started...';
          c.startPolling();
        });
      } else {
        $timeout(function() {
          c.data.processing = false;
          c.data.error = 'Upload failed';
        });
      }
    };

    xhr.onerror = function() {
      $timeout(function() {
        c.data.processing = false;
        c.data.error = 'Network error';
      });
    };

    xhr.send(file);
  };

  // ── Polling ───────────────────────────────────────────────
  c.startPolling = function() {
    pollCount = 0;

    pollTimer = $interval(function() {
      pollCount++;

      c.server.get({ action: 'poll', sysId: c.data.sysId })
        .then(function(response) {

          if (response.data.result) {
            $interval.cancel(pollTimer);
            c.data.processing = false;
            c.data.result     = response.data.result;

          } else if (pollCount >= MAX_POLLS) {
            $interval.cancel(pollTimer);
            c.data.processing = false;
            c.data.error = 'Timeout after 6 minutes';

          } else {
            c.data.statusMsg = 'Processing... ' + (pollCount * 10) + 's';
          }

        });

    }, 10000);
  };

  // ── Risk badge ────────────────────────────────────────────
  c.getRiskClass = function(risk) {
    if (!risk) return '';
    var r = risk.toLowerCase();
    if (r.includes('low')) return 'risk-low';
    if (r.includes('high')) return 'risk-high';
    return 'risk-medium';
  };

  // ── Summary points ────────────────────────────────────────
  c.getSummaryPoints = function(summary) {
    if (!summary) return [];
    return summary.split(/,\s*-\s*/);
  };

  // ── Reset ─────────────────────────────────────────────────
  c.reset = function() {
    if (pollTimer) $interval.cancel(pollTimer);

    c.rawFile = null;
    c.data = {};
  };

  $scope.$on('$destroy', function() {
    if (pollTimer) $interval.cancel(pollTimer);
  });

};

sp_widget.css:
.upload-zone {
  border: 2px dashed #c0cdd6;
  padding: 40px;
  text-align: center;
  cursor: pointer;
}

.upload-zone.drag-over {
  border-color: #1782c5;
  background: #eef6fb;
}

.result-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 12px;
}

.result-card {
  background: #f7f9fb;
  padding: 12px;
  border-radius: 8px;
}

.result-card.highlight {
  background: #eef6fb;
  border: 1px solid #1782c5;
}

.result-label {
  font-size: 11px;
  color: #7a8fa0;
}

.result-value {
  font-size: 16px;
  font-weight: bold;
}

.risk-low { background: #d4edda; }
.risk-medium { background: #fff3cd; }
.risk-high { background: #f8d7da; }
