/* RATIOS TABLE */
.ratios-table-box {
  margin-top: 20px;
  background: #f4f8fc;
  padding: 15px;
  border-radius: 8px;
}

.ratios-table {
  width: 100%;
  border-collapse: collapse;
}

.ratios-table td {
  padding: 8px 10px;
  border-bottom: 1px solid #e0e0e0;
}

.ratio-key {
  font-weight: 600;
  color: #2d3f50;
}

.ratio-value {
  text-align: right;
  color: #1782c5;
  font-weight: 600;
}

sp_widget.script:
(function() {

  // ACTION: POLL
  if (input && input.action === 'poll') {
    if (!input.sysId) {
      data.pollError = 'No sysId provided.';
      return;
    }

    var rec = new GlideRecord('x_birl3_clm_corpository_ocr');

    if (rec.get(input.sysId)) {

      var nameVal = rec.getValue('company_name');

      if (nameVal && nameVal.trim() !== '') {

        data.result = {
          number: rec.getValue('number'),
          name_of_company: rec.getValue('company_name'),

          rating: rec.getValue('rating'),
          risk_index: rec.getValue('risk_index'),

          credit_limit: rec.getValue('credit_limit'),

          total_current_liabilities: rec.getValue('total_current_liabilities'),
          total_non_current_liabilities: rec.getValue('total_non_current_liabilities'),

          total_equity: rec.getValue('total_equity'),
          total_equity_liabilities: rec.getValue('total_equity_liabilities'),

          // 🔥 NEW FIELDS
          total_assets: rec.getValue('total_assets'),
          total_revenue: rec.getValue('total_revenue'),
          total_non_current_assets: rec.getValue('total_non_current_assets'),
          total_expenses: rec.getValue('total_expenses'),
          total_current_assets: rec.getValue('total_current_assets'),
          ebitda: rec.getValue('ebitda'),
          networth: rec.getValue('networth'),
          ratios: rec.getValue('ratios'),

          ai_summary: rec.getValue('ai_summary')
        };
      }

    } else {
      data.pollError = 'Record not found: ' + input.sysId;
    }

    return;
  }

  // ACTION: CREATE_RECORD
  if (input && input.action === 'create_record') {
    try {
      var ocr = new GlideRecord('x_birl3_clm_corpository_ocr');
      ocr.initialize();

      var sysId = ocr.insert();

      if (!sysId) {
        data.serverError = 'Failed to create OCR record.';
        return;
      }

      data.sysId = sysId;

    } catch (e) {
      data.serverError = 'Error creating record: ' + e.message;
    }

    return;
  }

})();
